  "quiz": [
    {
      "id": "q1",
      "q": "刘单车最初被判刑，是因为什么事？",
      "options": [
        {
          "key": "A",
          "text": "偷了矿上的铜线"
        },
        {
          "key": "B",
          "text": "骑走了一辆别人的自行车"
        },
        {
          "key": "C",
          "text": "私拉电线引起火灾"
        },
        {
          "key": "D",
          "text": "打伤了电机厂的工头"
        }
      ],
      "answer": "B",
      "clue": "wa_liu_2",
      "explain": "电工房墙上的车铃下贴着判决书：盗窃自行车一辆，判处有期徒刑一年。此后的十九年，都是甄善美一次次加上去的。"
    },
    {
      "id": "q2",
      "q": "撒德巴递了九次假释申请，甄善美每一次的批示是什么？",
      "options": [
        {
          "key": "A",
          "text": "改造态度不端正"
        },
        {
          "key": "B",
          "text": "浪费粮食，再留一年"
        },
        {
          "key": "C",
          "text": "饺子包得好，再留一年"
        },
        {
          "key": "D",
          "text": "伙房缺人，暂缓"
        }
      ],
      "answer": "C",
      "clue": "wa_sa_4",
      "explain": "撒德巴褥子底下的九份假释申请，批示一栏都是同一句：饺子包得好，再留一年。"
    },
    {
      "id": "q3",
      "q": "四年前编号0417的服刑人员出事后，监狱上报的说法是什么？",
      "options": [
        {
          "key": "A",
          "text": "夜间越狱，坠入罐笼井"
        },
        {
          "key": "B",
          "text": "突发急病，抢救不及"
        },
        {
          "key": "C",
          "text": "关押水牢期间意外"
        },
        {
          "key": "D",
          "text": "与人斗殴受伤"
        }
      ],
      "answer": "A",
      "clue": "wa_he_3",
      "explain": "医务室抽屉里0417的档案袋里，死亡报告的结论一栏写着夜间越狱、坠入罐笼井，由何必呢签字、鬼见愁副署。"
    },
    {
      "id": "q4",
      "q": "大嘴巴被甄善美“暂存”在监狱账上的是什么？",
      "options": [
        {
          "key": "A",
          "text": "一年的奖金"
        },
        {
          "key": "B",
          "text": "三年、三十六个月的工资"
        },
        {
          "key": "C",
          "text": "他娘的看病钱"
        },
        {
          "key": "D",
          "text": "广播室的设备款"
        }
      ],
      "answer": "B",
      "clue": "wa_da_4",
      "explain": "广播室抽屉里压着三十六张工资条，每张都盖着暂存两个红字。"
    },
    {
      "id": "q5",
      "q": "甄善美多年来把钱和那本加刑账藏在哪里？",
      "options": [
        {
          "key": "A",
          "text": "办公室的保险柜"
        },
        {
          "key": "B",
          "text": "皮箱的夹层"
        },
        {
          "key": "C",
          "text": "水牢坑底铁格栅下的砖洞"
        },
        {
          "key": "D",
          "text": "罐笼井底"
        }
      ],
      "answer": "C",
      "clue": "wa_sl_5",
      "explain": "水牢坑底一块铁格栅下面是个砖洞，洞壁的铁锈印和甄善美怀里那只铁皮盒子对得上，盒里是钞票和加刑账本。"
    },
    {
      "id": "q6",
      "q": "0417的遗物里那只红布虎头鞋，原本是谁留给他的？",
      "options": [
        {
          "key": "A",
          "text": "他的生母，鞋是一对，她留下了另一只"
        },
        {
          "key": "B",
          "text": "吴理头，给他剃头时送的"
        },
        {
          "key": "C",
          "text": "撒德巴，从饺子铺带进来的"
        },
        {
          "key": "D",
          "text": "甄善美，当作奖励发的"
        }
      ],
      "answer": "A",
      "clue": "wa_he_3",
      "explain": "吴理头记得0417说过，那只虎头鞋是他娘留给他的，他要拿着它去找另一只；档案袋里婴儿照片上穿的正是一双，值班室的铁皮饼干盒里也有一只同样绣着歪歪扭扭虎眼的鞋。"
    }
  ],
